import { useId, useRef, type KeyboardEvent, type ReactNode } from "react";
import "./TabStrip.css";

export interface Tab {
  readonly id: string;
  readonly label: string;
}

export interface TabStripProps {
  readonly tabs: readonly Tab[];
  readonly selected: string;
  readonly onSelect: (id: string) => void;
  readonly children?: ReactNode;
}

export function TabStrip({ tabs, selected, onSelect, children }: TabStripProps) {
  const baseId = useId();
  const buttonRefs = useRef<Map<string, HTMLButtonElement>>(new Map());

  const selectedIndex = tabs.findIndex((tab) => tab.id === selected);
  // Roving tabindex: the selected tab (or the first tab, if the selection is
  // unknown) is the single tab stop in the tablist.
  const stopIndex = selectedIndex >= 0 ? selectedIndex : 0;
  const activeTab = tabs[stopIndex];

  const tabDomId = (id: string): string => `${baseId}-tab-${id}`;
  const panelDomId = `${baseId}-panel`;

  const moveTo = (index: number): void => {
    const tab = tabs[index];
    if (tab === undefined) {
      return;
    }
    onSelect(tab.id);
    buttonRefs.current.get(tab.id)?.focus();
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number): void => {
    const count = tabs.length;
    if (count === 0) {
      return;
    }

    switch (event.key) {
      case "ArrowRight":
        moveTo((index + 1) % count);
        break;
      case "ArrowLeft":
        moveTo((index - 1 + count) % count);
        break;
      case "Home":
        moveTo(0);
        break;
      case "End":
        moveTo(count - 1);
        break;
      default:
        return;
    }
    event.preventDefault();
  };

  return (
    <div className="tabstrip">
      <div className="tabstrip-list" role="tablist" aria-orientation="horizontal">
        {tabs.map((tab, index) => {
          const isSelected = tab.id === selected;
          return (
            <button
              key={tab.id}
              ref={(element) => {
                if (element) {
                  buttonRefs.current.set(tab.id, element);
                } else {
                  buttonRefs.current.delete(tab.id);
                }
              }}
              type="button"
              role="tab"
              id={tabDomId(tab.id)}
              className="tabstrip-tab"
              aria-selected={isSelected}
              aria-controls={panelDomId}
              tabIndex={index === stopIndex ? 0 : -1}
              onClick={() => onSelect(tab.id)}
              onKeyDown={(event) => handleKeyDown(event, index)}
            >
              {tab.label}
            </button>
          );
        })}
      </div>
      <div
        role="tabpanel"
        id={panelDomId}
        className="tabstrip-panel"
        aria-labelledby={activeTab ? tabDomId(activeTab.id) : undefined}
        tabIndex={0}
      >
        {children}
      </div>
    </div>
  );
}
