/*
 * TabStrip styles.
 *
 * Colours are custom properties. Day values are the default. Night values
 * apply when an ancestor carries data-theme="night". Both sets are tuned for
 * calm, low-glare reading and keep text contrast at or above WCAG AA.
 */

.tabstrip {
  --tabstrip-bg: #f6f3ec;
  --tabstrip-border: #d9d3c4;
  --tabstrip-fg: #2b3440;
  --tabstrip-muted: #5f6b78;
  --tabstrip-hover: #ebe6d9;
  --tabstrip-accent: #2f7d74;
  --tabstrip-panel-bg: #fffdf8;
  --tabstrip-focus: #2f7d74;

  display: flex;
  flex-direction: column;
  min-height: 0;
  color: var(--tabstrip-fg);
  background: var(--tabstrip-bg);
  font-family: inherit;
}

[data-theme="night"] .tabstrip {
  --tabstrip-bg: #161b22;
  --tabstrip-border: #2c3440;
  --tabstrip-fg: #d6dde6;
  --tabstrip-muted: #8b96a5;
  --tabstrip-hover: #1f2630;
  --tabstrip-accent: #6cc3b5;
  --tabstrip-panel-bg: #1b2129;
  --tabstrip-focus: #8fd8cb;
}

.tabstrip-list {
  display: flex;
  gap: 0.25rem;
  padding: 0 1rem;
  border-bottom: 1px solid var(--tabstrip-border);
  overflow-x: auto;
  scrollbar-width: none;
}

.tabstrip-list::-webkit-scrollbar {
  display: none;
}

.tabstrip-tab {
  position: relative;
  flex: 0 0 auto;
  margin: 0;
  padding: 0.75rem 0.875rem;
  border: 0;
  border-radius: 0.375rem 0.375rem 0 0;
  background: transparent;
  color: var(--tabstrip-muted);
  font: inherit;
  font-size: 0.9375rem;
  font-weight: 500;
  line-height: 1.25;
  white-space: nowrap;
  cursor: pointer;
  transition: color 160ms ease, background-color 160ms ease;
}

.tabstrip-tab:hover {
  color: var(--tabstrip-fg);
  background: var(--tabstrip-hover);
}

/* The selected state is marked by colour, weight, and an underline, so it
   does not depend on colour alone. */
.tabstrip-tab[aria-selected="true"] {
  color: var(--tabstrip-accent);
  font-weight: 600;
  background: transparent;
}

.tabstrip-tab[aria-selected="true"]::after {
  content: "";
  position: absolute;
  left: 0.5rem;
  right: 0.5rem;
  bottom: -1px;
  height: 2px;
  border-radius: 2px 2px 0 0;
  background: var(--tabstrip-accent);
}

.tabstrip-tab:focus {
  outline: none;
}

.tabstrip-tab:focus-visible,
.tabstrip-panel:focus-visible {
  outline: 2px solid var(--tabstrip-focus);
  outline-offset: 2px;
}

.tabstrip-panel {
  flex: 1 1 auto;
  min-height: 0;
  padding: 1.25rem 1rem;
  background: var(--tabstrip-panel-bg);
  overflow: auto;
}

@media (prefers-reduced-motion: reduce) {
  .tabstrip-tab {
    transition: none;
  }
}
